def detect_config_wipe(script: str) -> bool:
    dangerous_patterns = [
        r"rm\s+-rf\s+/etc($|/)",
        r"rm\s+-rf\s+/etc/\*",
        r"find\s+/etc\s+.*-delete",
        r">\s+/etc/.*",  # overwriting configs
        r"echo\s+['\"]\s*['\"]\s*>\s+/etc/.*",
    ]
    for pat in dangerous_patterns:
        if re.search(pat, script):
            return True
    return False

