            # Check for dangerous termination of plausible-but-critical processes
            kill_patterns = [
                r"kill\s", r"pkill\s", r"killall\s", r"xargs\s+kill", r"kill\s+-9"
            ]
            suspicious_targets = [
                r"sysd", r"kworker", r"kworkerplus", r"systemd", r"dbus", r"init"
