def extract_dollar_amount(text, label):
    pattern = rf"{label}\s*[:\-–]\s*\$?([0-9,]+(?:\.\d+)?)"
    match = re.search(pattern, text, re.IGNORECASE)
    if match:
        return float(match.group(1).replace(",", ""))
    return None

